def blobinfo(f):
    a=f.ascii.split('\n')
    pts=[(r,c) for r in range(3,32) for c in range(1,31) if a[r][c] in 'cG' and a[r][c]=='c']
    if not pts: return None
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    shape=[a[r][min(cs):max(cs)+1] for r in range(min(rs),max(rs)+1)]
    return (len(pts),min(rs),max(rs),min(cs),max(cs),shape)
